import { createFileRoute } from "@tanstack/react-router";
import { useServerFn } from "@tanstack/react-start";
import { type FormEvent, type ReactNode, useEffect, useState } from "react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { saveSighting } from "@/lib/sighting-functions";
import {
  type CreateSighting,
  type CreateSightingInput,
  createSightingInputSchema,
  SAVE_FAILURE_MESSAGE,
  type Sighting,
} from "@/lib/sightings";

export const Route = createFileRoute("/")({
  component: CapturePage,
});

// biome-ignore lint/style/useConsistentTypeDefinitions: AGENTS.md prefers types unless extending.
type LabelTime = {
  labelDate: string;
  labelTime: string;
};

const getCurrentDeviceTime = (): Date => new Date();
const LABEL_TIME_PATTERN = /^([01]\d|2[0-3]):([0-5]\d)$/;
const STORE_OPENING_MINUTE = 9 * 60;
const STORE_CLOSING_MINUTE = 20 * 60;

function padTimePart(value: number): string {
  return value.toString().padStart(2, "0");
}

export function getDeviceLabelTime(date: Date): LabelTime {
  return {
    labelDate: `${date.getFullYear()}-${padTimePart(date.getMonth() + 1)}-${padTimePart(date.getDate())}`,
    labelTime: `${padTimePart(date.getHours())}:${padTimePart(date.getMinutes())}`,
  };
}

function labelTimeToMinute(labelTime: string): number | undefined {
  const match = LABEL_TIME_PATTERN.exec(labelTime);
  if (!match) {
    return undefined;
  }

  return Number(match[1]) * 60 + Number(match[2]);
}

function isOutsideStoreHours(labelMinute: number | undefined): boolean {
  return (
    labelMinute !== undefined &&
    (labelMinute < STORE_OPENING_MINUTE || labelMinute > STORE_CLOSING_MINUTE)
  );
}

function formatSavedLabelTime(sighting: Sighting): string {
  const date = new Date(`${sighting.labelDate}T12:00:00`);
  const hour = Math.floor(sighting.labelMinute / 60);
  const minute = sighting.labelMinute % 60;
  const time = new Intl.DateTimeFormat("en-US", {
    hour: "numeric",
    minute: "2-digit",
  }).format(new Date(2000, 0, 1, hour, minute));
  const formattedDate = new Intl.DateTimeFormat("en-US", {
    day: "numeric",
    month: "long",
    year: "numeric",
  }).format(date);

  return `Saved label time for ${formattedDate} at ${time}.`;
}

export function CapturePage(): ReactNode {
  const save = useServerFn(saveSighting);
  const saveSightingFromRoute: CreateSighting = async (input) => {
    return await save({ data: input });
  };

  return <CaptureForm saveSighting={saveSightingFromRoute} />;
}

export function CaptureForm({
  now = getCurrentDeviceTime,
  saveSighting,
}: Readonly<{
  now?: () => Date;
  saveSighting: CreateSighting;
}>): ReactNode {
  const [labelTime, setLabelTime] = useState<LabelTime>(() =>
    getDeviceLabelTime(now())
  );
  const [errorMessage, setErrorMessage] = useState<string>();
  const [isSaving, setIsSaving] = useState(false);
  const [savedSighting, setSavedSighting] = useState<Sighting>();

  useEffect(() => {
    setLabelTime(getDeviceLabelTime(now()));
  }, [now]);

  const labelMinute = labelTimeToMinute(labelTime.labelTime);
  const outsideStoreHours = isOutsideStoreHours(labelMinute);

  const handleSave = async (): Promise<void> => {
    if (isSaving) {
      return;
    }

    if (labelMinute === undefined) {
      setErrorMessage("Enter a complete clock time.");
      return;
    }

    const input: CreateSightingInput = {
      labelDate: labelTime.labelDate,
      labelMinute,
    };
    const validation = createSightingInputSchema.safeParse(input);
    if (!validation.success) {
      setErrorMessage("Enter a complete real date.");
      return;
    }

    setErrorMessage(undefined);
    setIsSaving(true);
    try {
      const result = await saveSighting(validation.data);

      if (!result.ok) {
        setErrorMessage(result.message);
        return;
      }

      setSavedSighting(result.sighting);
    } catch {
      setErrorMessage(SAVE_FAILURE_MESSAGE);
    } finally {
      setIsSaving(false);
    }
  };

  const handleSubmit = async (
    event: FormEvent<HTMLFormElement>
  ): Promise<void> => {
    event.preventDefault();
    await handleSave();
  };

  return (
    <div className="mx-auto flex min-h-screen w-full max-w-md flex-col px-4 py-8">
      <header className="mb-8">
        <p className="font-medium text-muted-foreground text-sm">
          Chicken Tracking
        </p>
        <h1 className="mt-2 font-semibold text-4xl tracking-tight">Capture</h1>
        <p className="mt-2 text-muted-foreground">
          Record the label time exactly as printed.
        </p>
      </header>
      <Card>
        <CardHeader>
          <CardTitle>Label time</CardTitle>
        </CardHeader>
        <CardContent>
          <form
            aria-label="Capture label time"
            className="grid gap-6"
            noValidate
            onSubmit={handleSubmit}
          >
            <div className="grid gap-2">
              <Label htmlFor="label-time">Label time</Label>
              <Input
                aria-describedby={
                  outsideStoreHours ? "store-hours-warning" : undefined
                }
                className="h-16 text-3xl"
                id="label-time"
                onChange={(event) => {
                  setLabelTime((current) => ({
                    ...current,
                    labelTime: event.target.value,
                  }));
                }}
                required
                type="time"
                value={labelTime.labelTime}
              />
              {outsideStoreHours ? (
                <p
                  className="text-sm text-warning-foreground"
                  id="store-hours-warning"
                >
                  Outside store hours
                </p>
              ) : null}
            </div>
            <div className="grid gap-2">
              <Label htmlFor="label-date">Label date</Label>
              <Input
                id="label-date"
                onChange={(event) => {
                  setLabelTime((current) => ({
                    ...current,
                    labelDate: event.target.value,
                  }));
                }}
                required
                type="date"
                value={labelTime.labelDate}
              />
            </div>
            {errorMessage ? (
              <p
                aria-live="assertive"
                className="text-destructive text-sm"
                role="alert"
              >
                {errorMessage}
              </p>
            ) : null}
            {isSaving ? (
              <output aria-live="polite">Saving label time…</output>
            ) : null}
            {savedSighting ? (
              <output aria-live="polite" className="text-success-foreground">
                {formatSavedLabelTime(savedSighting)}
              </output>
            ) : null}
            <Button
              className="h-12 text-base"
              disabled={isSaving}
              type="submit"
            >
              Save label time
            </Button>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}
import "@testing-library/jest-dom/vitest";

import {
  cleanup,
  fireEvent,
  render,
  screen,
  waitFor,
} from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";

import { type CreateSighting, SAVE_FAILURE_MESSAGE } from "@/lib/sightings";

import { CaptureForm } from "./app/index";

const DEFAULT_CLOCK = new Date(2026, 7, 11, 14, 5);
const SAVED_LABEL_TIME_MESSAGE =
  /Saved label time for August 11, 2026 at 8:00 AM/;

afterEach(cleanup);

function renderCapture(saveSighting: CreateSighting): void {
  render(<CaptureForm now={() => DEFAULT_CLOCK} saveSighting={saveSighting} />);
}

function renderCaptureAt(
  now: Date,
  saveSighting: CreateSighting = vi.fn()
): void {
  render(<CaptureForm now={() => now} saveSighting={saveSighting} />);
}

describe("Capture", () => {
  it("defaults to the device's local date and minute", () => {
    renderCapture(vi.fn());

    expect(screen.getByLabelText("Label date")).toHaveValue("2026-08-11");
    expect(screen.getByLabelText("Label time")).toHaveValue("14:05");
  });

  it.each([
    [new Date(2026, 0, 1, 0, 0), "2026-01-01", "00:00"],
    [new Date(2026, 0, 31, 23, 59), "2026-01-31", "23:59"],
    [new Date(2026, 1, 1, 0, 0), "2026-02-01", "00:00"],
    [new Date(2026, 11, 31, 23, 59), "2026-12-31", "23:59"],
    [new Date(2027, 0, 1, 0, 0), "2027-01-01", "00:00"],
  ])("uses the new local day and minute across calendar boundaries: %s", (now, labelDate, labelTime) => {
    renderCaptureAt(now);

    expect(screen.getByLabelText("Label date")).toHaveValue(labelDate);
    expect(screen.getByLabelText("Label time")).toHaveValue(labelTime);
  });

  it("warns but allows a label time outside store hours", async () => {
    const saveSighting = vi.fn().mockResolvedValue({
      ok: true,
      sighting: {
        createdAt: new Date("2026-08-11T19:05:00.000Z"),
        doneness: null,
        id: 1,
        labelDate: "2026-08-11",
        labelMinute: 480,
        updatedAt: new Date("2026-08-11T19:05:00.000Z"),
      },
    });
    renderCapture(saveSighting);

    fireEvent.change(screen.getByLabelText("Label time"), {
      target: { value: "08:00" },
    });
    expect(screen.getByText("Outside store hours")).toBeTruthy();

    fireEvent.click(screen.getByRole("button", { name: "Save label time" }));

    await waitFor(() => {
      expect(saveSighting).toHaveBeenCalledWith({
        labelDate: "2026-08-11",
        labelMinute: 480,
      });
    });
    expect(screen.getByText(SAVED_LABEL_TIME_MESSAGE)).toBeTruthy();
  });

  it("submits when Enter is pressed from a label field", async () => {
    const saveSighting = vi.fn().mockResolvedValue({
      ok: true,
      sighting: {
        createdAt: new Date("2026-08-11T19:05:00.000Z"),
        doneness: null,
        id: 1,
        labelDate: "2026-08-11",
        labelMinute: 845,
        updatedAt: new Date("2026-08-11T19:05:00.000Z"),
      },
    });
    renderCapture(saveSighting);

    fireEvent.submit(screen.getByRole("form", { name: "Capture label time" }));

    await waitFor(() => {
      expect(saveSighting).toHaveBeenCalledWith({
        labelDate: "2026-08-11",
        labelMinute: 845,
      });
    });
  });

  it("blocks invalid input before save", () => {
    const saveSighting = vi.fn();
    renderCapture(saveSighting);

    fireEvent.change(screen.getByLabelText("Label date"), {
      target: { value: "2026-02-30" },
    });
    fireEvent.click(screen.getByRole("button", { name: "Save label time" }));

    expect(screen.getByText("Enter a complete real date.")).toBeTruthy();
    expect(saveSighting).not.toHaveBeenCalled();
  });

  it("prevents duplicate saves while communicating progress", async () => {
    let resolveSave:
      | ((value: Awaited<ReturnType<CreateSighting>>) => void)
      | undefined;
    const saveSighting = vi.fn(
      () =>
        new Promise<Awaited<ReturnType<CreateSighting>>>((resolve) => {
          resolveSave = resolve;
        })
    );
    renderCapture(saveSighting);

    const saveButton = screen.getByRole("button", { name: "Save label time" });
    fireEvent.click(saveButton);
    fireEvent.click(saveButton);

    expect(saveSighting).toHaveBeenCalledTimes(1);
    expect(screen.getByRole("status")).toHaveTextContent("Saving label time");
    expect(saveButton).toBeDisabled();

    resolveSave?.({
      ok: false,
      message:
        "Unable to save label time. Check your connection and try again.",
    });
    await waitFor(() => {
      expect(screen.getByRole("alert")).toHaveTextContent(
        "Unable to save label time"
      );
    });
  });

  it("keeps entered facts available after an initial save failure", async () => {
    const saveSighting = vi.fn().mockResolvedValue({
      ok: false,
      message:
        "Unable to save label time. Check your connection and try again.",
    });
    renderCapture(saveSighting);

    fireEvent.change(screen.getByLabelText("Label date"), {
      target: { value: "2024-02-29" },
    });
    fireEvent.change(screen.getByLabelText("Label time"), {
      target: { value: "20:30" },
    });
    fireEvent.click(screen.getByRole("button", { name: "Save label time" }));

    await waitFor(() => {
      expect(screen.getByRole("alert")).toBeTruthy();
    });
    expect(screen.getByLabelText("Label date")).toHaveValue("2024-02-29");
    expect(screen.getByLabelText("Label time")).toHaveValue("20:30");
    expect(screen.queryByText("Sighting saved")).toBeNull();
  });

  it("recovers when the save request rejects", async () => {
    const saveSighting = vi
      .fn()
      .mockRejectedValue(new Error("Network unavailable"));
    renderCapture(saveSighting);

    fireEvent.click(screen.getByRole("button", { name: "Save label time" }));

    await waitFor(() => {
      expect(screen.getByRole("alert")).toHaveTextContent(SAVE_FAILURE_MESSAGE);
    });
    expect(
      screen.getByRole("button", { name: "Save label time" })
    ).toBeEnabled();
    expect(screen.getByLabelText("Label date")).toHaveValue("2026-08-11");
    expect(screen.getByLabelText("Label time")).toHaveValue("14:05");
  });
});
